beginning.embedded_functions:
//each function name should be prefixed by em_
/**
* Return:
* - 0: ok
* - 1: invalid
* - 2: NULL
*/
static inline int em_check_ngap_setup_storm(uint32_t ngap_setup_request_count, uint32_t time_window_ms) {
  // Define a threshold for the number of NGSetupRequest messages within the time window.
  // This value should be tuned based on the expected normal network behavior.
  uint32_t threshold = 5; // Example threshold.  Adjust as needed.

  if (ngap_setup_request_count > threshold) {
    return 1; // Indicates a storm
  } else {
    return 0; // Indicates normal behavior
  }
}
